begin
  begin
    select 1 into w_ambienti
      from a_ambienti
     where rownum = 1
    ;
  exception
    when no_data_found then
         w_ambienti := 0;
    when others then
         w_ambienti := -1;
  end;

  if w_ambienti = 0 then
